  }
  return out;
40→}

function runGitDiff(repoPath, baseRef, headRef, rangeOp) {
  const range = `${baseRef}${rangeOp}${headRef}`;
  const r = spawnSync('git', ['-C', repoPath, 'diff', '--no-ext-diff', '--find-renames', range], {
    encoding: 'utf8',
    maxBuffer: 12 * 1024 * 1024,
  });
