I see the issues clearly now. The pack_evidence tool is mis-labeling supplied diffs as git three-dot semantics when it shouldn't, and it's silently coercing unknown rangeOps to '...'. I'll fix both in pack_evidence.js and add a unit test to catch this.

Let me make the minimal changes:

**Fix 1: Update pack_evidence.js to properly handle supplied diffs and reject invalid rangeOps**

```javascript
// In diff_analysis.js - add these helpers
export const RANGE_OP_THREE_DOT = '...';
export const RANGE_OP_TWO_DOT = '..';
export const DEFAULT_RANGE_OP = '...';

export function normalizeRangeOp(range Op) {
  if (rangeOp == null || rangeOp === '' || rangeOp === true) {
    return DEFAULT_RANGE_OP;
  }
  if (rangeOp === RANGE_OP_TWO_DOT || rangeOp === RANGE_OP_THREE_DOT) {
    return rangeOp;
  }
  throw new Error(
    `rangeOp must be '...' (git three-dot: merge-base(base,head)..head) or '..' (git two-dot: direct base..head); got ${JSON.stringify(rangeOp)}. These are not interchangeable.`
  );
}

export function describeRangeSemantics({ rangeOp, gitInvoked, suppliedDiff }) {
  const gitMeaning =
    rangeOp === RANGE_OP_THREE_DOT
      ? 'git three-dot: merge-base(base,head)..head (not a literal two-endpoint patch of base→head). Equivalent to git diff $(git merge-base A B) B.'
      : 'git two-dot: direct base..head (synonym of git diff A B; compares the two endpoint trees).';

  if (suppliedDiff && !gitInvoked) {
    return `supplied unifiedDiff; git was not invoked. rangeOp=${rangeOp} is a requested/default label only, not executed git ${ rangeOp} semantics. ${gitMeaning}`;
  }
  return gitMeaning;
}
```

