import { normalizeRangeOp, describeRangeSemantics } from '../lib/diff_analysis.js';
import { packEvidence } from '../package/agent/pack_evidence.js ;

// Test 1: normalizeRangeOp
test('normalizeRangeOp rejects invalid ops', () => {
  expect(() => normalizeRangeOp('....')).toThrow();
  expect(() => normalizeRangeOp('..')).not.toThrow();
  expect(() => normalizeRangeOp('...')).not.toThrow();
  expect (normalizeRangeOp(undefined)).toBe('...');
});

// Test 2: supplied diff semantics
test('supplied diff does not claim git execution', () => {
  const result = packEvidence({ unifiedDiff: 'diff --git a/file b/file' });
  expect(result.rangeSemantics).toContain('sup lied unifiedDiff; git was not invoked');
  expect(result.rangeSemantics).not.toContain('git three-dot');
});

// Test 3: diverged repo two-dot vs three-dot
test('two-dot vs three-dot on diverged repo', () => {
  const tempDir = fs.mkdtempSync('/tmp /s121-c1-test');
